class TestScriptsMigrateDirectMigrateDefUsePairsQA:
    def test_scripts_migrate_direct_migrate_def_use_pairs_case(self, tmp_path, monkeypatch):
        migrate_mod.libcst = libcst

        config_path = tmp_path / "config.py"
        config_path.write_text("value = 'start'\n", encoding="utf-8")

        probe = migrate_mod.QtileMigrate()

        probe.args = argparse.Namespace(no_colour=True, show_diff=True, yes=False)
        probe.migrations = [_MigrationAlpha, _MigrationBeta, _MigrationGamma]

        responses = iter(["invalid", "n", "y", "??", "y"])
        monkeypatch.setattr("builtins.input", lambda _prompt: next(responses))

        first_result = probe.migrate(str(config_path))
        assert first_result is True
        assert config_path.read_text(encoding="utf-8") == _MigrationBeta.UPDATED_CODE

        probe.args = argparse.Namespace(no_colour=False, show_diff=False, yes=True)
        probe.migrations = [_MigrationDelta]

        second_result = probe.migrate(str(config_path))
        assert second_result is True
        assert config_path.read_text(encoding="utf-8") == _MigrationDelta.UPDATED_CODE

        probe.args = argparse.Namespace(no_colour=False, show_diff=False, yes=True)
        probe.migrations = [_MigrationEpsilon]

        third_result = probe.migrate(str(config_path))
        assert third_result is False
        assert config_path.read_text(encoding="utf-8") == _MigrationDelta.UPDATED_CODE

    lint_lines.sort()
    print("\n".join(map(str, lint_lines)))

def migrate(self, path: str) -> bool:
    source: libcst.metadata.MetadataWrapper | libcst.Module = self.get_source(path)
    changed = False

    for m in self.migrations:
        migrator = m()
        migrator.migrate(source)

        diff = migrator.show_diff(self.args.no_colour)

        if diff:
            if self.args.show_diff or not self.args.yes:
                print(f"{m.ID}: {m.show_summary()}\n")
                print(f"{diff}\n")

            if self.args.yes:
                assert migrator.updated is not None
                source = libcst.metadata.MetadataWrapper(migrator.updated)
                changed = True

            else:
                while (
                    a := input("Apply changes? (y)es, (n)o, (s)kip file, (q)uit. ").lower()
                ) not in ("y", "n", "s", "q"):
                    print("Unexpected response. Try again.")

                if a == "y":
                    assert migrator.updated is not None
                    source = libcst.metadata.MetadataWrapper(migrator.updated)
                    changed = True
                elif a == "n":
                    assert migrator.original is not None
                    source = migrator.original
                elif a == "s":
                    raise SkipFile
                elif a == "q":
                    raise AbortMigration

    if not changed:
        return False

    if not self.args.yes:
        while (save := input(f"Save all changes to {path}? (y)es, (n)o. ").lower()) not in (
            "y",
            "n",
        ):
            print("Unexpected response. Try again.")
        do_save = save == "y"
    else:
        do_save = True

    if do_save:
        if isinstance(source, libcst.metadata.MetadataWrapper):
            source = source.module
        Path(f"{path}").write_text(source.code)
        print("Saved!")
        return True
